#!/usr/bin/env python3
"""
test_overall.py — one-command validation for MARK LIV.

This file replaces the old standalone check_*.py scripts. The individual suites
are embedded here so the repository root stays clean, but each suite still runs
in its own Python process with a virtual __file__ in the repository root. That
keeps the old headless/no-Qt isolation properties and lets this runner produce a
single PASS / FAIL / SKIPPED report.

Run everything:  python test_overall.py
Run one suite:   python test_overall.py --suite plugins
Show full logs:  python test_overall.py --verbose
"""
from __future__ import annotations

import argparse
import base64
import os
import re
import subprocess
import sys
import time
import zlib
from dataclasses import dataclass
from pathlib import Path

for _stream in ("stdout", "stderr"):
    try:
        getattr(sys, _stream).reconfigure(encoding="utf-8", errors="replace")
    except Exception:
        pass

REPO = Path(__file__).resolve().parent
SUITE_ORDER = [('wake_word', 'check_wake_word.py'), ('wake_isolation', 'check_wake_isolation.py'), ('session_memory', 'check_session_memory.py'), ('dashboard_auth', 'check_dashboard_auth.py'), ('plugins', 'check_plugins.py'), ('silence', 'check_silence.py')]
SUITE_SOURCES = {'wake_word': '', 'wake_isolation': '', 'session_memory': '', 'dashboard_auth': '', 'plugins': '', 'silence': ''}


@dataclass
class SuiteResult:
    name: str
    file_name: str
    returncode: int
    seconds: float
    stdout: str
    stderr: str
    passed: int
    failed: int
    skipped: int
    status: str


def _source(name: str) -> str:
    return zlib.decompress(base64.b64decode(SUITE_SOURCES[name])).decode("utf-8")


def _run_embedded_suite(name: str) -> int:
    file_name = dict(SUITE_ORDER)[name]
    virtual_file = str(REPO / file_name)
    globs = {
        "__name__": "__main__",
        "__file__": virtual_file,
        "__package__": None,
        "__builtins__": __builtins__,
    }
    if str(REPO) not in sys.path:
        sys.path.insert(0, str(REPO))
    try:
        exec(compile(_source(name), virtual_file, "exec"), globs)
        return 0
    except SystemExit as e:
        code = e.code
        if code is None:
            return 0
        if isinstance(code, int):
            return code
        print(code)
        return 1


def _parse_counts(stdout: str, stderr: str, rc: int, name: str) -> tuple[int, int, int, str]:
    text = stdout + "\n" + stderr
    passed = len(re.findall(r"\[PASS\]", text))
    failed = len(re.findall(r"\[FAIL\]", text))
    skipped = len(re.findall(r"(?:^\s*SKIP:|\[SKIP\]|\bSKIP:)", text, flags=re.IGNORECASE | re.MULTILINE))

    # Some legacy checkers predate the [PASS]/[FAIL] convention. Treat their
    # intentional no-feature result as a skipped capability instead of a failed
    # product test, while still failing on a non-zero process exit.
    if name == "wake_word" and "openwakeword ist NICHT installiert" in text and rc == 0:
        skipped = max(skipped, 1)
        status = "SKIPPED"
    elif name == "silence" and rc == 0:
        # check_silence is an environment probe: it prints the gate/audio report
        # and may legitimately skip PortAudio in CI. The actionable result is
        # still the captured report.
        status = "PASS"
        if "probe skipped" in text.lower():
            skipped = max(skipped, 1)
    elif rc == 0 and failed == 0:
        status = "PASS"
    else:
        status = "FAIL"
        if failed == 0:
            failed = 1
    return passed, failed, skipped, status


def _run_suite(name: str, file_name: str) -> SuiteResult:
    t0 = time.time()
    env = dict(os.environ)
    env["PYTHONIOENCODING"] = "utf-8:replace"
    proc = subprocess.run(
        [sys.executable, str(Path(__file__).resolve()), "--_run-suite", name],
        cwd=str(REPO), text=True, encoding="utf-8", errors="replace",
        stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env,
    )
    seconds = time.time() - t0
    passed, failed, skipped, status = _parse_counts(proc.stdout, proc.stderr, proc.returncode, name)
    return SuiteResult(name, file_name, proc.returncode, seconds,
                       proc.stdout, proc.stderr, passed, failed, skipped, status)


def _print_suite_log(result: SuiteResult, verbose: bool) -> None:
    if verbose or result.status == "FAIL":
        if result.stdout:
            print("\n" + result.stdout.rstrip())
        if result.stderr:
            print("\n[stderr]")
            print(result.stderr.rstrip())
    elif result.status == "SKIPPED":
        # Give the reason, not the whole wall of diagnostic text.
        lines = [ln for ln in result.stdout.splitlines()
                 if "SKIP" in ln.upper() or "NICHT INSTALLIERT" in ln.upper()]
        for ln in lines[:4]:
            print(f"      {ln}")


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Run MARK LIV's full validation suite.")
    parser.add_argument("--suite", choices=[name for name, _ in SUITE_ORDER],
                        help="run only one suite")
    parser.add_argument("--verbose", action="store_true",
                        help="print each suite's full output")
    parser.add_argument("--_run-suite", choices=[name for name, _ in SUITE_ORDER],
                        help=argparse.SUPPRESS)
    args = parser.parse_args(argv)

    if args._run_suite:
        return _run_embedded_suite(args._run_suite)

    selected = [(n, f) for n, f in SUITE_ORDER if not args.suite or n == args.suite]
    t0 = time.time()
    print("=" * 72)
    print(" MARK LIV — overall validation")
    print("=" * 72)
    print(f"Python: {sys.version.split()[0]}  ({sys.executable})")
    print(f"Repo:   {REPO}")

    results: list[SuiteResult] = []
    for name, file_name in selected:
        print(f"\n── {name} " + "─" * max(0, 60 - len(name)))
        result = _run_suite(name, file_name)
        results.append(result)
        print(f"  [{result.status}] {name} — "
              f"pass={result.passed} fail={result.failed} skip={result.skipped} "
              f"exit={result.returncode} time={result.seconds:.1f}s")
        _print_suite_log(result, args.verbose)

    total_pass = sum(r.passed for r in results)
    total_fail = sum(r.failed for r in results)
    total_skip = sum(r.skipped for r in results)
    failed_suites = [r for r in results if r.status == "FAIL"]
    skipped_suites = [r for r in results if r.status == "SKIPPED"]

    print("\n" + "=" * 72)
    print("OVERALL REPORT")
    print(f"Suites: {len(results)}  Passed suites: {sum(r.status == 'PASS' for r in results)}  "
          f"Failed suites: {len(failed_suites)}  Skipped suites: {len(skipped_suites)}")
    print(f"Checks: pass={total_pass} fail={total_fail} skip={total_skip}  "
          f"Time: {time.time() - t0:.1f}s")
    if failed_suites:
        print("\nFAILED SUITES:")
        for r in failed_suites:
            print(f"  - {r.name}, exit {r.returncode}")
        return 1
    if skipped_suites:
        print("\nSKIPPED SUITES:")
        for r in skipped_suites:
            print(f"  - {r.name}")
    print("\nAll non-skipped suites passed.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
